import json, hashlib, math
LOW=(2,2,0,0,0,0,0,0); UP=(4,4,4,4,4,4,4,4)
DEGS=list(range(4,33)); HS=[1,2,3,4]
def wt(x): return sum(x)
def partitions(pos,prev,rem,a):
    if pos==len(a):
        if rem==0: yield ()
        return
    lo=a[pos]
    for x in range(min(prev,rem),lo-1,-1):
        for tail in partitions(pos+1,x,rem-x,a): yield (x,)+tail
def basis(d):
    return list(partitions(0,UP[0],d,LOW))
def horizontal(lam,mu):
    # mu/lam is horizontal iff mu_i >= lam_i >= mu_{i+1}
    return all(mu[i]>=lam[i] and lam[i]>=mu[i+1] for i in range(7)) and mu[7]>=lam[7]
def smith_diag(A):
    # Exact elementary row/column reduction; returns diagonal invariants.
    A=[r[:] for r in A]; m=len(A); n=len(A[0]) if m else 0; k=0
    while k<m and k<n:
        candidates=[(abs(A[i][j]),i,j) for i in range(k,m) for j in range(k,n) if A[i][j]]
        if not candidates: break
        _,i,j=min(candidates); A[k],A[i]=A[i],A[k]
        for r in A: r[k],r[j]=r[j],r[k]
        while True:
            changed=False
            for i in range(k+1,m):
                if A[i][k]:
                    q=A[i][k]//A[k][k]
                    A[i]=[A[i][z]-q*A[k][z] for z in range(n)]
                    if abs(A[i][k])<abs(A[k][k]) and A[i][k]: A[k],A[i]=A[i],A[k]
                    changed=True; break
            if changed: continue
            for j in range(k+1,n):
                if A[k][j]:
                    q=A[k][j]//A[k][k]
                    for r in range(m): A[r][j]-=q*A[r][k]
                    if abs(A[k][j])<abs(A[k][k]) and A[k][j]:
                        for r in range(m): A[r][k],A[r][j]=A[r][j],A[r][k]
                    changed=True; break
            if changed: continue
            bad=None
            for i in range(k+1,m):
                for j in range(k+1,n):
                    if A[i][j]%A[k][k]: bad=(i,j); break
                if bad: break
            if not bad: break
            i,j=bad
            # add row i to pivot row, exposing nondivisibility in pivot column
            A[k]=[A[k][z]+A[i][z] for z in range(n)]
        if A[k][k]<0: A[k]=[-x for x in A[k]]
        k+=1
    return [A[i][i] for i in range(k)]
allout=[]
for d in DEGS:
    cols=basis(d); ci={x:i for i,x in enumerate(cols)}; rows=[]
    for t in HS:
        for lam in basis(d-t) if d>=t else []:
            targets=[mu for mu in cols if horizontal(lam,mu)]
            row=[0]*len(cols)
            for mu in targets: row[ci[mu]]=1
            rows.append({'hDegree':t,'source':list(lam),'targetCoefficients':row,'zero':not targets})
    M=[x['targetCoefficients'] for x in rows]
    diag=smith_diag(M)
    if any(x<=0 or (i and x%diag[i-1]) for i,x in enumerate(diag)): raise AssertionError('invalid smith diagonal')
    allout.append({'degree':d,'orderedBasis': [list(x) for x in cols],'labelledPieriRows':rows,'smithDiagonal':diag,'rank':len(diag),'quotientFreeRank':len(cols)-len(diag),'torsionInvariantFactors':[x for x in diag if x>1],'zeroRowCount':sum(x['zero'] for x in rows)})
result={'inputs':{'lower':list(LOW),'upper':list(UP),'degrees':DEGS,'hDegrees':HS},'supportDegreeRange':[wt(LOW),wt(UP)],'enumeratedAllSupportDegrees':True,'columnOrder':'reverse lexicographic from recursive decreasing parts','rowOrder':'hDegree ascending, then source partition reverse lexicographic','degreeData':allout}
text=json.dumps(result,separators=(',',':'),sort_keys=True)
print(text)
print(json.dumps({'outputSha256':hashlib.sha256(text.encode()).hexdigest(),'allSmithFactorsAreOne':all(all(x==1 for x in d['smithDiagonal']) for d in allout),'totalQuotientFreeRank':sum(d['quotientFreeRank'] for d in allout)},sort_keys=True))
